import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷一·18","description":"易小帖 - 卷一·18","frontmatter":{"title":"卷一·18","description":"易小帖 - 卷一·18"},"headers":[],"relativePath":"classics/yixiaotie/018.md","filePath":"classics/yixiaotie/018.md"}'),o={name:"classics/yixiaotie/018.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷一·18",tabindex:"-1"},[r("卷一·18 "),e("a",{class:"header-anchor",href:"#卷一·18","aria-label":"Permalink to “卷一·18”"},"​")],-1),e("p",null,"虞氏易有巽為魚，語見於剝姤及中孚三卦。以剝有貫魚，姤有包魚，中孚有豚魚故也。但姤及中孚皆有下巽，而剝獨無有。予嘗諦觀剝姤二卦，皆以陰陽升降消息為義，魚雖陰類，然在澤有魚，而在山無魚，故剝及五爻已成艮山，姤及四爻亦漸成觀卦，大艮之象，是剝五貫魚，喜其尚有魚，而姤四無魚，則正憂其魚之自此無也。因於中孚豚魚，則以巽為解，於姤之包魚，則又兌澤為解，以兌澤與艮山反也。且剝無巽也，若《仲氏易》，《說卦》下亦脫巽為魚句，則檢㸃不及，非有意去取耳。",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
